class FileHandle {
    FILE* file;
public:
    explicit FileHandle(const char* path, const char* mode)
        : file(fopen(path, mode)) {}
    ~FileHandle() { if (file) fclose(file); }
    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;
};

struct HeavyData { int x; };
std::unique_ptr<HeavyData> uptr1 = std::make_unique<HeavyData>(10);
// uptr1 is moved, uptr2 takes ownership
std::unique_ptr<HeavyData> uptr2 = std::move(uptr1);
// Resource automatically freed when uptr2 goes out of scope.

struct Widget { void action() {} };
std::shared_ptr<Widget> sptr1 = std::make_shared<Widget>();
std::shared_ptr<Widget> sptr2 = sptr1;
// Reference count (2) automatically managed.
sptr1->action();
// Resource freed only after both sptr1 and sptr2 are destroyed.
